        if(size)   *size = to_read;
        if(offset) *offset = rar->cstate.last_unstore_ptr;

        rar->file.bytes_remaining -= to_read;
        rar->cstate.last_unstore_ptr += to_read;

        update_crc(rar, p, to_read);
        return ARCHIVE_OK;
