        }

        if(name_size == 0) {
                archive_set_error(&a->archive, ARCHIVE_ERRNO_FILE_FORMAT,
                                "No filename specified");

                return ARCHIVE_FATAL;
        }

        memcpy(name_utf8_buf, p, name_size);
        name_utf8_buf[name_size] = 0;
        if(ARCHIVE_OK != consume(a, name_size)) {
